# Cada item: (materia, texto_base, enunciado, gabarito 'C'|'E', comentario com artigo)
# Itens com o mesmo texto_base aparecem juntos, no estilo Cebraspe.
L = "LGPD"
A = "ANPD e Regulação"
C = "Direito Constitucional"
D = "Direito Administrativo"
S = "Segurança da Informação"

T1 = "Julgue os itens a seguir, relativos aos conceitos e ao âmbito de aplicação da Lei nº 13.709/2018 (LGPD)."
T2 = "Julgue os itens seguintes, acerca dos fundamentos e dos princípios da proteção de dados pessoais previstos na LGPD."
T3 = "Julgue os itens a seguir, a respeito das bases legais do tratamento e do consentimento na LGPD."
T4 = "Julgue os itens seguintes, relativos a dados de crianças, anonimização, pseudonimização e prazos de atendimento ao titular."
T5 = "Julgue os itens a seguir, acerca dos direitos do titular, da conservação dos dados, das decisões automatizadas e da responsabilização dos agentes de tratamento."
T6 = "Julgue os itens seguintes, relativos a incidentes de segurança, sanções administrativas, transferência internacional de dados e encarregado, nos termos da LGPD."
T7 = "Julgue os itens a seguir, a respeito da natureza jurídica, da estrutura e das competências da Agência Nacional de Proteção de Dados (ANPD), consideradas a LGPD e a Lei nº 15.352/2026."
T8 = "Julgue os itens seguintes, com base na Lei nº 13.848/2019, que dispõe sobre a gestão, a organização, o processo decisório e o controle social das agências reguladoras."
T9 = "Julgue os itens a seguir, relativos à descentralização prevista na Lei nº 13.848/2019 e às resoluções da ANPD sobre encarregado, agentes de pequeno porte e comunicação de incidentes."
T10 = "Julgue os itens seguintes, acerca de resoluções da ANPD que regulamentam dosimetria, fiscalização, transferência internacional e prazos de comunicação de incidente."
T11 = "Julgue os itens a seguir, relativos à proteção de dados pessoais no texto constitucional e às competências legislativas e materiais da União."
T12 = "Julgue os itens seguintes, acerca de remédios constitucionais, princípios da administração pública, estabilidade e criação de autarquias."
T13 = "Julgue os itens a seguir, com fundamento na Lei nº 9.784/1999, na Lei nº 14.133/2021 e na Lei nº 8.429/1992, esta última com a redação da Lei nº 14.230/2021."
T14 = "Julgue os itens seguintes, relativos à Lei nº 12.527/2011 (LAI), à organização da administração pública e à autotutela."
T15 = "Um perito foi acionado para examinar o computador de um controlador após incidente de segurança que pode ter afetado dados pessoais. A respeito da segurança da informação e da coleta de evidências digitais, julgue os itens a seguir."
T16 = "Julgue os itens seguintes, relativos a criptografia, autenticação, normas da família ISO/IEC 27000, ransomware e resposta a incidentes."
T17 = "Ainda a respeito de incidentes com dados pessoais, da cadeia de custódia de vestígios e das boas práticas forenses, julgue os itens a seguir."
T18 = "Julgue os itens seguintes, acerca de medidas de segurança da LGPD, anonimização, pseudonimização e preservação da integridade de evidências digitais."

Q = [
(L, T1, "De acordo com a LGPD, considera-se dado pessoal sensível, entre outros, o dado sobre origem racial ou étnica, convicção religiosa, opinião política, saúde ou vida sexual, bem como o dado genético ou biométrico, quando vinculado a uma pessoa natural.", "C", "Art. 5º, II, da Lei nº 13.709/2018."),
(L, T1, "Dados financeiros, como renda e patrimônio, integram o rol de dados pessoais sensíveis previsto no art. 5º, II, da LGPD.", "E", "Art. 5º, II, da Lei nº 13.709/2018. Renda e patrimônio podem ser dados pessoais, mas não constam do rol de dados sensíveis."),
(L, T1, "Operador é a pessoa natural ou jurídica, de direito público ou privado, que realiza o tratamento de dados pessoais em nome do controlador.", "C", "Art. 5º, VII, da Lei nº 13.709/2018."),
(L, T1, "O encarregado é a pessoa a quem competem as decisões referentes ao tratamento de dados pessoais.", "E", "Quem decide é o controlador (art. 5º, VI). O encarregado atua como canal de comunicação entre o controlador, os titulares e a ANPD (art. 5º, VIII, com a redação da Lei nº 15.352/2026)."),
(L, T1, "A LGPD não se aplica ao tratamento de dados pessoais realizado para fins exclusivamente jornalísticos e artísticos.", "C", "Art. 4º, II, alínea “a”, da Lei nº 13.709/2018."),
(L, T1, "A LGPD não se aplica ao tratamento de dados pessoais realizado para fins exclusivamente comerciais de comércio eletrônico.", "E", "O art. 4º da Lei nº 13.709/2018 não exclui o comércio eletrônico. Entre as exclusões estão, por exemplo, fins exclusivamente jornalísticos e artísticos (inciso II, “a”) e o tratamento por pessoa natural para fins particulares e não econômicos (inciso I)."),

(L, T2, "A autodeterminação informativa é um dos fundamentos da disciplina da proteção de dados pessoais, nos termos do art. 2º da LGPD.", "C", "Art. 2º, II, da Lei nº 13.709/2018."),
(L, T2, "A supremacia do interesse público sobre o privado é fundamento expressamente arrolado no art. 2º da LGPD.", "E", "O art. 2º, I a VII, não menciona a supremacia do interesse público, princípio típico do direito administrativo. Fundamentos da LGPD incluem, entre outros, o respeito à privacidade, a autodeterminação informativa e o desenvolvimento econômico e tecnológico e a inovação."),
(L, T2, "O princípio da necessidade limita o tratamento ao mínimo necessário para a realização de suas finalidades, com abrangência dos dados pertinentes, proporcionais e não excessivos em relação às finalidades do tratamento de dados.", "C", "Art. 6º, III, da Lei nº 13.709/2018."),
(L, T2, "O princípio da adequação consiste na demonstração, pelo agente, da adoção de medidas eficazes e capazes de comprovar o cumprimento das normas de proteção de dados pessoais, inclusive da eficácia dessas medidas.", "E", "Essa é a definição do princípio da responsabilização e prestação de contas (art. 6º, X). A adequação (art. 6º, II) é a compatibilidade do tratamento com as finalidades informadas ao titular."),
(L, T2, "O princípio da finalidade exige a realização do tratamento para propósitos legítimos, específicos, explícitos e informados ao titular, sem possibilidade de tratamento posterior de forma incompatível com essas finalidades.", "C", "Art. 6º, I, da Lei nº 13.709/2018."),
(L, T2, "O princípio da não discriminação veda qualquer tratamento que estabeleça diferenciação entre titulares, ainda que a diferenciação seja lícita e não abusiva.", "E", "O art. 6º, IX, da Lei nº 13.709/2018 impede o tratamento para fins discriminatórios ilícitos ou abusivos, e não qualquer diferenciação lícita."),

(L, T3, "Cabe ao controlador o ônus da prova de que o consentimento foi obtido em conformidade com o disposto na LGPD.", "C", "Art. 8º, § 2º, da Lei nº 13.709/2018."),
(L, T3, "Autorizações genéricas para o tratamento de dados pessoais são válidas, desde que fornecidas por escrito.", "E", "Art. 8º, § 4º, da Lei nº 13.709/2018: são nulas as autorizações genéricas para o tratamento de dados pessoais."),
(L, T3, "O consentimento pode ser revogado a qualquer momento, mediante manifestação expressa do titular, por procedimento gratuito e facilitado.", "C", "Art. 8º, § 5º, da Lei nº 13.709/2018."),
(L, T3, "A proteção do crédito é hipótese legal de tratamento tanto no art. 7º quanto no rol do art. 11 da LGPD, aplicável a dados pessoais sensíveis.", "E", "A proteção do crédito consta do art. 7º, X, mas não do art. 11, que disciplina o tratamento de dados sensíveis. Também não figura no art. 11 o legítimo interesse (art. 7º, IX)."),
(L, T3, "Dados pessoais sensíveis poderão ser tratados sem fornecimento de consentimento do titular quando o tratamento for indispensável para garantia da prevenção à fraude e à segurança do titular, nos processos de identificação e autenticação de cadastro em sistemas eletrônicos, resguardados os direitos mencionados no referido dispositivo.", "C", "Art. 11, II, “g”, da Lei nº 13.709/2018, que ressalva o caso de prevalecerem direitos e liberdades do titular que exijam a proteção dos dados pessoais."),
(L, T3, "É permitido o tratamento de dados de saúde para a obtenção de vantagem econômica, inclusive na seleção de riscos na contratação de plano de saúde, desde que haja consentimento do titular.", "E", "Art. 11, § 5º, da Lei nº 13.709/2018: é vedada a comunicação ou o uso compartilhado entre controladores de dados sensíveis referentes à saúde com objetivo de obter vantagem econômica, inclusive na seleção de riscos na contratação de plano de saúde, ressalvadas as hipóteses legais ali previstas."),

(L, T4, "O tratamento de dados pessoais de criança deverá ser realizado com o consentimento específico e em destaque dado por pelo menos um dos pais ou pelo responsável legal, ressalvadas as hipóteses legais.", "C", "Art. 14, § 1º, da Lei nº 13.709/2018. O § 3º admite coleta sem consentimento quando a finalidade for contatar os pais ou o responsável legal, uma única vez e sem armazenamento, ou para a proteção da criança."),
(L, T4, "O tratamento de dados pessoais de criança depende, em qualquer hipótese, do consentimento de ambos os pais, não se admitindo exceção.", "E", "O art. 14, § 1º, exige o consentimento de pelo menos um dos pais ou do responsável legal, e o § 3º prevê hipóteses de coleta sem consentimento."),
(L, T4, "A pseudonimização é o tratamento por meio do qual um dado perde a possibilidade de associação, direta ou indireta, a um indivíduo, senão pelo uso de informação adicional mantida separadamente pelo controlador em ambiente controlado e seguro.", "C", "Art. 13, § 4º, da Lei nº 13.709/2018."),
(L, T4, "O dado anonimizado é considerado dado pessoal para todos os efeitos da LGPD, ainda que não exista possibilidade razoável de reversão do processo de anonimização.", "E", "Art. 12, caput, da Lei nº 13.709/2018: os dados anonimizados não serão considerados dados pessoais, salvo quando o processo de anonimização ao qual foram submetidos for revertido, ou quando, com esforços razoáveis, puder ser revertido."),
(L, T4, "A confirmação de existência ou o acesso a dados pessoais, quando fornecidos por meio de declaração clara e completa, deverá ser feito no prazo de até 15 dias, contado da data do requerimento do titular.", "C", "Art. 19, II, da Lei nº 13.709/2018."),
(L, T4, "Em formato simplificado, a confirmação de existência de tratamento ou o acesso aos dados pessoais deve ser atendido no prazo de 30 dias.", "E", "Art. 19, I, da Lei nº 13.709/2018: em formato simplificado, o atendimento deve ser imediato."),

(L, T5, "São direitos do titular, entre outros, a portabilidade dos dados a outro fornecedor de serviço ou produto, mediante requisição, e a informação sobre a possibilidade de não fornecer consentimento e sobre as consequências da negativa.", "C", "Art. 18, V e VIII, da Lei nº 13.709/2018."),
(L, T5, "O titular pode exigir indenização diretamente da ANPD por tratamento irregular de dados pessoais praticado por terceiro.", "E", "A reparação de danos é devida pelo controlador ou pelo operador (art. 42 da Lei nº 13.709/2018). A ANPD aplica as sanções administrativas (art. 55-K) e não indeniza o titular no lugar do agente de tratamento."),
(L, T5, "Os dados pessoais serão eliminados após o término de seu tratamento, autorizada a conservação para uso exclusivo do controlador, vedado seu acesso por terceiro, e desde que anonimizados os dados.", "C", "Art. 16, IV, da Lei nº 13.709/2018. Outras hipóteses de conservação estão nos incisos I a III (obrigação legal ou regulatória, estudo por órgão de pesquisa e transferência a terceiro, observados os requisitos da Lei)."),
(L, T5, "A revisão de decisões tomadas unicamente com base em tratamento automatizado de dados pessoais deve, por força do art. 20 da LGPD, ser realizada obrigatoriamente por pessoa natural.", "E", "O caput do art. 20, na redação da Lei nº 13.853/2019, assegura o direito à revisão, mas não exige que ela seja feita por pessoa natural. O § 3º que previa essa exigência foi vetado."),
(L, T5, "Os agentes de tratamento não serão responsabilizados quando provarem que o dano decorre de culpa exclusiva do titular dos dados ou de terceiro.", "C", "Art. 43, III, da Lei nº 13.709/2018. O mesmo artigo prevê, ainda, as hipóteses de não ter realizado o tratamento (I) e de não ter havido violação à legislação de proteção de dados (II)."),
(L, T5, "A mera adoção de programa de governança em privacidade, ainda que tenha havido violação à lei, exclui a responsabilidade do controlador.", "E", "Programa de governança é circunstância a ser considerada na dosimetria da sanção (art. 52, § 1º, IX, da Lei nº 13.709/2018), e não excludente de responsabilidade dos arts. 42 e 43."),

(L, T6, "O controlador deverá comunicar à autoridade nacional e ao titular dos dados a ocorrência de incidente de segurança que possa acarretar risco ou dano relevante aos titulares.", "C", "Art. 48, caput, da Lei nº 13.709/2018. O § 1º remete a definição do prazo à autoridade nacional e lista o conteúdo mínimo da comunicação."),
(L, T6, "A comunicação de qualquer incidente de segurança, independentemente de risco ou dano relevante, deve ser feita apenas à polícia judiciária, em até 24 horas.", "E", "O art. 48, caput, da Lei nº 13.709/2018 exige comunicação à autoridade nacional e ao titular quando o incidente puder acarretar risco ou dano relevante. O prazo é definido pela autoridade nacional, e não há, nesse artigo, dever de comunicar somente à polícia em 24 horas."),
(L, T6, "A multa simples prevista na LGPD pode ser de até 2% do faturamento da pessoa jurídica de direito privado, grupo ou conglomerado no Brasil no seu último exercício, excluídos os tributos, limitada, no total, a R$ 50.000.000,00 por infração.", "C", "Art. 52, II, da Lei nº 13.709/2018. O teto de R$ 50 milhões é por infração, e não por ano."),
(L, T6, "Aos órgãos e às entidades públicas podem ser aplicadas, entre outras, as sanções de multa simples e de multa diária previstas no art. 52 da LGPD.", "E", "Art. 52, § 3º, da Lei nº 13.709/2018: aos órgãos e entidades públicos aplicam-se as sanções dos incisos I, IV, V, VI, X, XI e XII. As multas dos incisos II e III não estão incluídas."),
(L, T6, "A transferência internacional de dados pessoais pode ser realizada por mera decisão unilateral do operador, independentemente de garantias adequadas ou de outra hipótese legal.", "E", "O art. 33 da Lei nº 13.709/2018 elenca hipóteses específicas (nível adequado de proteção, cláusulas-padrão, consentimento específico e em destaque, autorização da autoridade nacional, entre outras). Não há transferência por mera decisão do operador."),
(L, T6, "A identidade e as informações de contato do encarregado deverão ser divulgadas publicamente, de forma clara e objetiva, preferencialmente no sítio eletrônico do controlador.", "C", "Art. 41, § 1º, da Lei nº 13.709/2018. As atividades do encarregado estão no § 2º; o § 3º admite que a ANPD dispense a indicação conforme a natureza e o porte da entidade ou o volume de operações."),

(A, T7, "Com a redação dada pela Lei nº 15.352/2026, a ANPD é autarquia de natureza especial vinculada ao Ministério da Justiça e Segurança Pública, com patrimônio próprio e com sede e foro no Distrito Federal, nos termos da Lei nº 13.848/2019.", "C", "Art. 55-A da Lei nº 13.709/2018, com a redação da Lei nº 15.352/2026, que também a dotou de autonomia funcional, técnica, decisória, administrativa e financeira."),
(A, T7, "A ANPD é órgão da Presidência da República, desprovido de personalidade jurídica própria.", "E", "Essa era a configuração anterior. O art. 55-A da LGPD, com a redação da Lei nº 15.352/2026, criou a ANPD como autarquia de natureza especial, com personalidade jurídica própria, vinculada ao Ministério da Justiça e Segurança Pública."),
(A, T7, "Integram a ANPD, entre outros, o Conselho Diretor, o Conselho Nacional de Proteção de Dados Pessoais e da Privacidade, a Corregedoria, a Ouvidoria, a Procuradoria e a Auditoria.", "C", "Art. 55-C da Lei nº 13.709/2018. A Procuradoria (V-A) e a Auditoria (V-B) constam da redação dada pela Lei nº 15.352/2026."),
(A, T7, "O Conselho Diretor da ANPD é composto de 5 diretores, incluído o Diretor-Presidente.", "C", "Art. 55-D, caput, da Lei nº 13.709/2018."),
(A, T7, "O mandato dos membros do Conselho Diretor da ANPD é de 5 anos, nos termos do art. 55-D, § 3º, da LGPD.", "E", "O art. 55-D, § 3º, da Lei nº 13.709/2018 prevê mandato de 4 anos. A Lei nº 15.352/2026 não alterou esse parágrafo; seus arts. 12 e 17 tratam da manutenção dos mandatos em curso e da regra de transição para não coincidência (art. 50 da Lei nº 13.848/2019 e art. 4º da Lei nº 9.986/2000)."),
(A, T7, "A aplicação das sanções previstas na LGPD compete exclusivamente à ANPD.", "C", "Art. 55-K, caput, da Lei nº 13.709/2018. O parágrafo único determina que a ANPD articule sua atuação com outros órgãos e entidades com competências sancionatórias e normativas aferentes a temas de proteção de dados pessoais."),

(A, T8, "A natureza especial conferida à agência reguladora é caracterizada pela ausência de tutela ou de subordinação hierárquica, pela autonomia funcional, decisória, administrativa e financeira e pela investidura a termo de seus dirigentes e estabilidade durante os mandatos.", "C", "Art. 3º, caput, da Lei nº 13.848/2019."),
(A, T8, "A natureza especial das agências reguladoras as isenta do controle externo a cargo do Congresso Nacional, com o auxílio do Tribunal de Contas da União.", "E", "O art. 14 da Lei nº 13.848/2019 estabelece que o controle externo das agências é exercido pelo Congresso Nacional, com o auxílio do TCU. A autonomia do art. 3º não afasta esse controle."),
(A, T8, "O período de consulta pública sobre minutas e propostas de alteração de atos normativos de interesse geral dos agentes econômicos, consumidores ou usuários dos serviços prestados terá duração mínima de 45 dias, ressalvado caso excepcional de urgência e relevância, devidamente motivado.", "C", "Art. 9º, § 2º, da Lei nº 13.848/2019."),
(A, T8, "A pauta das reuniões deliberativas do conselho diretor ou da diretoria colegiada deverá ser disponibilizada no sítio eletrônico da agência com antecedência mínima de 15 dias úteis.", "E", "Art. 8º, § 1º, da Lei nº 13.848/2019: a antecedência mínima é de 3 dias úteis. A gravação deve ser disponibilizada em até 15 dias úteis (§ 3º) e a ata, em até 5 dias úteis após a aprovação (§ 4º)."),
(A, T8, "O ouvidor da agência reguladora terá mandato de 3 anos, vedada a recondução, e atuará sem subordinação hierárquica.", "C", "Arts. 22, caput e § 5º, e 23, § 1º, da Lei nº 13.848/2019 (o art. 23 trata do mandato de 3 anos, vedada a recondução)."),
(A, T8, "A análise de impacto regulatório (AIR) é facultativa em qualquer hipótese de edição ou de alteração de ato normativo de interesse geral de agentes econômicos, consumidores ou usuários dos serviços prestados.", "E", "Art. 6º, caput, da Lei nº 13.848/2019: a AIR deve preceder, nos termos de regulamento, a adoção e as propostas de alteração desses atos. O § 2º prevê hipóteses de dispensa; quando a AIR não for realizada, deve ser disponibilizada ao menos nota técnica ou documento equivalente que fundamente a proposta (§ 5º)."),

(A, T9, "Na descentralização de atividades das agências reguladoras federais para instâncias ou órgãos estaduais, distritais ou municipais, é vedada a delegação de competências normativas, nos termos da Lei nº 13.848/2019.", "C", "Art. 34, § 1º, da Lei nº 13.848/2019."),
(A, T9, "Uma vez celebrado o acordo de cooperação para a descentralização de atividades, a agência reguladora delegante deixa de ser instância recursal em relação às decisões do ente delegatário.", "E", "Art. 34, § 7º, da Lei nº 13.848/2019: a agência reguladora delegante permanece como instância superior e recursal para impugnação das decisões do ente delegatário."),
(A, T9, "A Lei nº 15.352/2026 incluiu a ANPD no rol das agências reguladoras a que se aplica a Lei nº 13.848/2019, na forma do art. 2º, XII, desta última.", "C", "Art. 8º da Lei nº 15.352/2026, que acrescentou o inciso XII ao art. 2º da Lei nº 13.848/2019."),
(A, T9, "A indicação do encarregado deve ser realizada por ato formal do agente de tratamento, nos termos do Regulamento aprovado pela Resolução CD/ANPD nº 18/2024.", "C", "Art. 3º do Regulamento aprovado pela Resolução CD/ANPD nº 18, de 16 de julho de 2024. O ato formal é documento escrito, datado e assinado, que designe pessoa natural ou jurídica."),
(A, T9, "Os agentes de tratamento de pequeno porte são, em regra, obrigados a indicar encarregado, nos termos da Resolução CD/ANPD nº 2/2022.", "E", "Art. 11 do Regulamento aprovado pela Resolução CD/ANPD nº 2, de 27 de janeiro de 2022: esses agentes não são obrigados a indicar encarregado. Se não o indicarem, devem disponibilizar um canal de comunicação com o titular (§ 1º)."),
(A, T9, "De acordo com o Regulamento aprovado pela Resolução CD/ANPD nº 15/2024, a comunicação de incidente de segurança à ANPD deverá ser realizada pelo controlador no prazo de 3 dias úteis, ressalvada legislação específica.", "C", "Art. 6º, caput, da Resolução CD/ANPD nº 15, de 24 de abril de 2024, que regulamenta o art. 48 da LGPD."),

(A, T10, "O prazo de 3 dias úteis da Resolução CD/ANPD nº 15/2024 equivale, para todos os efeitos, ao prazo de 72 horas corridas adotado no Regulamento Geral de Proteção de Dados da União Europeia, contado da ocorrência do ataque.", "E", "A Resolução CD/ANPD nº 15/2024, art. 6º, caput e § 1º, fixa 3 dias úteis, contados do conhecimento, pelo controlador, de que o incidente afetou dados pessoais, e não 72 horas corridas a partir da ocorrência do ataque."),
(A, T10, "As informações da comunicação de incidente de segurança à ANPD poderão ser complementadas, de maneira fundamentada, no prazo de 20 dias úteis, a contar da data da comunicação.", "C", "Art. 6º, § 3º, da Resolução CD/ANPD nº 15/2024."),
(A, T10, "A Resolução CD/ANPD nº 4/2023 aprova o Regulamento de Dosimetria e Aplicação de Sanções Administrativas.", "C", "Resolução CD/ANPD nº 4, de 24 de fevereiro de 2023."),
(A, T10, "A Resolução CD/ANPD nº 1/2021 aprova o Regulamento de Transferência Internacional de Dados e o conteúdo das cláusulas-padrão contratuais.", "E", "A Resolução CD/ANPD nº 1, de 28 de outubro de 2021, aprova o Regulamento do Processo de Fiscalização e do Processo Administrativo Sancionador. O regulamento de transferência internacional e das cláusulas-padrão é o da Resolução CD/ANPD nº 19, de 23 de agosto de 2024."),

(C, T11, "A proteção dos dados pessoais, inclusive nos meios digitais, foi expressamente incluída na Constituição Federal como direito fundamental no art. 5º, LXXIX, pela Emenda Constitucional nº 115/2022.", "C", "CF, art. 5º, LXXIX, incluído pela EC nº 115/2022."),
(C, T11, "A proteção dos dados pessoais, inclusive nos meios digitais, já constava, com a mesma abrangência do atual art. 5º, LXXIX, do art. 5º, X, na redação originária da Constituição de 1988.", "E", "O art. 5º, X, protege a intimidade, a vida privada, a honra e a imagem. O direito fundamental específico à proteção dos dados pessoais, inclusive nos meios digitais, foi incluído no art. 5º, LXXIX, pela EC nº 115/2022."),
(C, T11, "Compete privativamente à União legislar sobre proteção e tratamento de dados pessoais, nos termos do art. 22, XXX, da Constituição Federal.", "C", "CF, art. 22, XXX, incluído pela EC nº 115/2022."),
(C, T11, "A competência para legislar sobre proteção e tratamento de dados pessoais é concorrente entre a União, os Estados e o Distrito Federal, nos termos do art. 24, I, da Constituição Federal.", "E", "Trata-se de competência privativa da União (art. 22, XXX). O art. 24, I, trata de direito tributário, financeiro, penitenciário, econômico e urbanístico, e não de proteção de dados."),
(C, T11, "Organizar e fiscalizar a proteção e o tratamento de dados pessoais, nos termos da lei, é competência da União, conforme o art. 21, XXVI, da Constituição Federal.", "C", "CF, art. 21, XXVI, incluído pela EC nº 115/2022."),
(C, T11, "A Emenda Constitucional nº 115/2022 inseriu apenas o art. 5º, LXXIX, sem alterar os arts. 21 e 22 da Constituição Federal.", "E", "A EC nº 115/2022 também inseriu o art. 21, XXVI, e o art. 22, XXX."),

(C, T12, "O habeas data é o remédio constitucional cabível para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público.", "C", "CF, art. 5º, LXXII, “a”. O direito é regulamentado pela Lei nº 9.507/1997."),
(C, T12, "O habeas data também pode ser impetrado para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo.", "C", "CF, art. 5º, LXXII, “b”."),
(C, T12, "A aprovação prévia, pelo Senado Federal, da escolha de titulares de cargos que a lei determinar — como a dos dirigentes de agências reguladoras — está prevista no art. 52, III, “f”, da Constituição Federal.", "C", "CF, art. 52, III, “f”, expressamente referido no art. 55-D, § 1º, da LGPD e no art. 5º da Lei nº 13.848/2019 (e dispositivos correlatos sobre a escolha dos dirigentes)."),
(C, T12, "A autarquia poderá ser criada por decreto do Presidente da República, dispensada lei específica.", "E", "CF, art. 37, XIX: somente por lei específica pode ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação."),
(C, T12, "As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.", "C", "CF, art. 37, § 6º (responsabilidade objetiva da pessoa jurídica e regresso por dolo ou culpa)."),
(C, T12, "São princípios expressos da administração pública no caput do art. 37 da Constituição Federal a legalidade, a impessoalidade, a moralidade, a publicidade e a eficiência.", "C", "CF, art. 37, caput. A eficiência foi incluída pela EC nº 19/1998."),
(C, T12, "A motivação e a razoabilidade constam expressamente do caput do art. 37 da Constituição Federal.", "E", "O caput do art. 37 enumera legalidade, impessoalidade, moralidade, publicidade e eficiência. Motivação, razoabilidade e proporcionalidade aparecem, entre outros, no art. 2º da Lei nº 9.784/1999."),
(C, T12, "São estáveis, após três anos de efetivo exercício, os servidores nomeados para cargo de provimento efetivo em virtude de concurso público.", "C", "CF, art. 41, caput, com a redação da EC nº 19/1998. O § 4º condiciona a aquisição da estabilidade à avaliação especial de desempenho por comissão instituída para essa finalidade."),
(C, T12, "O ocupante exclusivamente de cargo em comissão adquire estabilidade após três anos de efetivo exercício, nos termos do art. 41 da Constituição Federal.", "E", "O art. 41, caput, aplica-se aos servidores nomeados para cargo de provimento efetivo em virtude de concurso público. Cargo em comissão é de livre nomeação e exoneração (art. 37, II)."),
(C, T12, "A criação de autarquia independe de lei, bastando autorização em lei complementar.", "E", "O art. 37, XIX, da CF exige lei específica para a criação de autarquia. Lei complementar não substitui essa exigência, e a autorização por lei específica é a regra prevista para empresa pública, sociedade de economia mista e fundação, não para a criação da autarquia."),


(D, T13, "Na Lei nº 9.784/1999, salvo disposição legal específica, o prazo para interposição de recurso administrativo é de 10 dias, contado da ciência ou da divulgação oficial da decisão.", "C", "Art. 59, caput, da Lei nº 9.784/1999."),
(D, T13, "O recurso administrativo é dirigido à autoridade que proferiu a decisão, a qual poderá reconsiderá-la no prazo de 5 dias.", "C", "Art. 56, § 1º, da Lei nº 9.784/1999."),
(D, T13, "O direito da Administração de anular os atos administrativos de que decorram efeitos favoráveis para os destinatários decai em 5 anos, contados da data em que foram praticados, salvo comprovada má-fé.", "C", "Art. 54, caput, da Lei nº 9.784/1999."),
(D, T13, "A Administração não pode anular os próprios atos quando eivados de vício de legalidade, dependendo, em qualquer hipótese, de decisão judicial.", "E", "A autotutela permite à Administração anular os próprios atos ilegais e revogá-los por conveniência ou oportunidade, respeitados os direitos adquiridos (art. 53 da Lei nº 9.784/1999 e Súmula 473 do STF)."),
(D, T13, "São modalidades de licitação, na Lei nº 14.133/2021, o pregão, a concorrência, o concurso, o leilão e o diálogo competitivo.", "C", "Art. 28 da Lei nº 14.133/2021."),
(D, T13, "A tomada de preços e o convite são modalidades de licitação previstas na Lei nº 14.133/2021.", "E", "Essas modalidades existiam na Lei nº 8.666/1993 e não foram reproduzidas no art. 28 da Lei nº 14.133/2021. O credenciamento, por sua vez, é procedimento auxiliar (art. 78), e não modalidade."),
(D, T13, "Após a Lei nº 14.230/2021, os atos de improbidade administrativa previstos na Lei nº 8.429/1992 exigem conduta dolosa.", "C", "Lei nº 8.429/1992, art. 1º, §§ 1º a 3º, com a redação da Lei nº 14.230/2021."),
(D, T13, "Na redação atual da Lei nº 8.429/1992, basta a culpa grave para a caracterização de ato de improbidade administrativa.", "E", "A Lei nº 14.230/2021 passou a exigir dolo. A culpa, ainda que grave, não basta para caracterizar improbidade na redação vigente do art. 1º, §§ 1º a 3º, da Lei nº 8.429/1992."),

(D, T14, "Na Lei de Acesso à Informação, os prazos máximos de restrição de acesso às informações classificadas como ultrassecreta, secreta e reservada são, respectivamente, de 25, 15 e 5 anos.", "C", "Art. 24, § 1º, da Lei nº 12.527/2011."),
(D, T14, "Na LAI, os prazos máximos de classificação das informações ultrassecreta, secreta e reservada são, respectivamente, de 50, 25 e 10 anos.", "E", "Os prazos corretos, no art. 24, § 1º, da Lei nº 12.527/2011, são 25, 15 e 5 anos."),
(D, T14, "Não sendo possível conceder o acesso imediato à informação requerida na forma da LAI, o órgão ou a entidade deverá, se não for o caso de negativa de acesso, atender ao pedido em prazo não superior a 20 dias, prorrogável por mais 10 dias, mediante justificativa expressa.", "C", "Art. 11, §§ 1º e 2º, da Lei nº 12.527/2011."),
(D, T14, "Na LAI, o pedido de acesso à informação deve ser atendido, no máximo, em 5 dias úteis, prazo improrrogável.", "E", "O art. 11, § 1º, da Lei nº 12.527/2011 prevê prazo de até 20 dias, prorrogável por mais 10 dias, nos termos do § 2º, quando não for possível o acesso imediato."),
(D, T14, "A ANPD, como autarquia, integra a administração pública indireta e possui personalidade jurídica de direito público.", "C", "Decreto-Lei nº 200/1967, arts. 4º, II, e 5º, I; art. 55-A da Lei nº 13.709/2018 (autarquia de natureza especial)."),
(D, T14, "A autarquia de natureza especial integra a administração direta, na qualidade de órgão do ministério supervisor.", "E", "Autarquia tem personalidade jurídica própria e integra a administração indireta (Decreto-Lei nº 200/1967, art. 4º, II, e art. 5º, I). O art. 55-A da LGPD confirma esse enquadramento para a ANPD, ainda que vinculada ao Ministério da Justiça e Segurança Pública."),
(D, T14, "Segundo a Súmula 473 do STF, a Administração pode anular seus próprios atos quando eivados de vícios que os tornem ilegais e revogá-los por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos.", "C", "Súmula 473 do STF, em harmonia com o art. 53 da Lei nº 9.784/1999."),
(D, T14, "A revogação é a forma de desfazer o ato administrativo ilegal, ao passo que a anulação desfaz o ato por motivo de conveniência ou de oportunidade.", "E", "É o inverso: a anulação ataca o ato ilegal; a revogação, o ato válido, por conveniência ou oportunidade (Súmula 473 do STF e art. 53 da Lei nº 9.784/1999)."),

(S, T15, "A tríade clássica da segurança da informação é composta pela confidencialidade, pela integridade e pela disponibilidade.", "C", "Modelo CIA, base conceitual da família ISO/IEC 27000. Autenticidade e não repúdio são propriedades complementares, e não os três pilares clássicos."),
(S, T15, "Na tríade clássica da segurança da informação, a autenticidade substitui a integridade, de modo que os três pilares passam a ser confidencialidade, autenticidade e disponibilidade.", "E", "A tríade clássica (CIA) permanece confidencialidade, integridade e disponibilidade. A autenticidade é propriedade complementar, não substituta da integridade."),
(S, T15, "Na coleta de evidências digitais, segundo a ordem de volatilidade da RFC 3227, deve-se coletar primeiro o conteúdo mais volátil, como registradores e cache da CPU e a memória volátil.", "C", "RFC 3227, item 2.1: a coleta segue do mais volátil (registradores, cache, memória) para o menos volátil (mídias de arquivo)."),
(S, T15, "Segundo a ordem de volatilidade da RFC 3227, a coleta deve começar pelos backups arquivados em mídia permanente, por serem a fonte mais confiável e estável.", "E", "Backups e mídias de arquivo estão no extremo menos volátil e devem ser coletados depois da memória volátil e de outros dados que se perdem facilmente (RFC 3227, item 2.1)."),
(S, T15, "O cálculo e o registro do hash (por exemplo, SHA-256) de uma imagem forense servem principalmente para demonstrar a integridade da evidência, permitindo verificar que ela não foi alterada.", "C", "A função de hash gera um resumo unidirecional. A comparação com o valor originalmente registrado integra a verificação de integridade e a documentação da cadeia de custódia (no processo penal, arts. 158-A a 158-F do CPP)."),
(S, T15, "O cálculo do hash cifra o conteúdo da evidência e, por isso, garante a confidencialidade do material periciado.", "E", "Hash não é cifra: é função de resumo, em regra irreversível, usada para integridade. Confidencialidade exige criptografia (ou outro controle de acesso), não o mero registro de hash."),
(S, T15, "O dispositivo de bloqueio de escrita (write blocker) é utilizado para permitir a leitura da mídia original sem alterar o seu conteúdo.", "C", "Boa prática forense, também refletida na ISO/IEC 27037: preservar a evidência original e trabalhar sobre cópia verificada por hash."),
(S, T15, "O write blocker deve ser utilizado para apagar de forma segura a mídia original depois de gerada a imagem forense.", "E", "O bloqueador de escrita existe precisamente para impedir alterações na mídia original, e não para apagá-la."),

(S, T16, "Na criptografia assimétrica, para enviar uma mensagem confidencial a Maria, João deve cifrá-la com a chave pública de Maria.", "C", "Somente a chave privada de Maria decifra o que foi cifrado com a sua chave pública. A assinatura digital, por sua vez, utiliza a chave privada do remetente."),
(S, T16, "Para garantir a confidencialidade de uma mensagem enviada a Maria, João deve cifrá-la com a sua própria chave privada.", "E", "Cifrar com a chave privada de João não impede que terceiros, de posse da chave pública de João, leiam a mensagem. Esse uso corresponde à assinatura digital, e não à confidencialidade."),
(S, T16, "A combinação de senha e de código gerado em aplicativo no aparelho celular do usuário constitui autenticação multifator.", "C", "Há fatores de categorias distintas: algo que se sabe (senha) e algo que se tem (o aparelho que gera o código)."),
(S, T16, "A combinação de senha e de pergunta secreta constitui autenticação multifator, por se tratar de dois fatores distintos.", "E", "Senha e pergunta secreta pertencem à mesma categoria (algo que se sabe) e, por isso, não caracterizam MFA."),
(S, T16, "A norma ABNT NBR ISO/IEC 27001 especifica requisitos para estabelecer, implementar, manter e melhorar continuamente um sistema de gestão de segurança da informação (SGSI).", "C", "A ISO/IEC 27001 é a norma de requisitos, passível de certificação. A ISO/IEC 27002 traz controles e diretrizes; a ISO/IEC 27701 estende o tema à privacidade; a ISO 31000 trata de gestão de riscos em geral."),
(S, T16, "A ISO/IEC 27002 é a norma certificável de requisitos do SGSI, ao passo que a ISO/IEC 27001 apenas apresenta diretrizes de controles, sem requisitos certificáveis.", "E", "A relação é a inversa: a 27001 traz os requisitos certificáveis do SGSI; a 27002 apresenta controles e diretrizes de implementação."),
(S, T16, "O ransomware, ataque em que se cifram dados da vítima e se exige pagamento para o fornecimento da chave, pode configurar incidente de segurança com dados pessoais, a ser examinado à luz do art. 48 da LGPD.", "C", "Art. 48 da Lei nº 13.709/2018: o controlador deve comunicar à autoridade nacional e ao titular o incidente que possa acarretar risco ou dano relevante. A extorsão com cifragem e, por vezes, com exfiltração (dupla extorsão) é hipótese típica."),
(S, T16, "No ciclo clássico de resposta a incidentes do NIST SP 800-61, revisão 2, a fase imediatamente posterior à detecção e análise é a de contenção, erradicação e recuperação.", "C", "NIST SP 800-61 r2: preparação; detecção e análise; contenção, erradicação e recuperação; atividades pós-incidente. A revisão 3 (2025) reorganiza o tema segundo as funções do CSF 2.0, mas o ciclo clássico da rev. 2 permanece referência frequente em provas."),

(S, T17, "No Regulamento aprovado pela Resolução CD/ANPD nº 15/2024, o prazo para a comunicação de incidente de segurança à ANPD conta-se da data da ocorrência do ataque, ainda que o controlador somente venha a conhecer o incidente semanas depois.", "E", "Art. 6º, § 1º, da Resolução CD/ANPD nº 15/2024: o prazo é contado do conhecimento, pelo controlador, de que o incidente afetou dados pessoais, e não da data da ocorrência."),
(S, T17, "Os prazos de comunicação de incidente de segurança previstos na Resolução CD/ANPD nº 15/2024 são contados em dobro para os agentes de tratamento de pequeno porte.", "C", "Art. 6º, § 8º, da Resolução CD/ANPD nº 15/2024, que remete ao Regulamento aprovado pela Resolução CD/ANPD nº 2/2022."),
(S, T17, "A cadeia de custódia de vestígios, no processo penal brasileiro, está disciplinada nos arts. 158-A a 158-F do Código de Processo Penal.", "C", "Dispositivos incluídos pela Lei nº 13.964/2019 (Pacote Anticrime)."),
(S, T17, "Considera-se cadeia de custódia, nos termos do art. 158-A do CPP, o conjunto de todos os procedimentos utilizados para manter e documentar a história cronológica do vestígio coletado em locais ou em vítimas de crimes, para rastrear sua posse e manuseio a partir de seu reconhecimento até o descarte.", "C", "Art. 158-A, caput, do CPP, com a redação da Lei nº 13.964/2019."),
(S, T17, "Uma vez coletado o vestígio e lavrado o auto correspondente, a legislação processual dispensa o registro das transferências e dos manuseios subsequentes, por já estar documentada a origem da evidência.", "E", "A cadeia de custódia (arts. 158-A a 158-F do CPP) exige a documentação contínua da posse e do manuseio do vestígio desde o reconhecimento até o descarte, e não apenas no momento da coleta."),
(S, T17, "A ISO/IEC 27037 estabelece diretrizes para identificação, coleta, aquisição e preservação de evidência digital.", "C", "ISO/IEC 27037, norma de referência para o tratamento inicial da evidência digital, em linha com a preservação da integridade e da cadeia de custódia."),
(S, T17, "A preparação é a primeira fase do ciclo clássico de resposta a incidentes descrito no NIST SP 800-61, revisão 2.", "C", "NIST SP 800-61 r2: a preparação antecede a detecção e análise."),
(S, T17, "Segundo o NIST SP 800-61, revisão 2, a notificação à imprensa é fase obrigatória e imediatamente posterior à preparação, devendo ocorrer antes de qualquer detecção ou análise.", "E", "Não há, nesse ciclo, fase obrigatória de “notificação à imprensa” entre a preparação e a detecção. A comunicação a interessados, quando cabível, insere-se nas atividades de resposta e pós-incidente, conforme o caso — e, envolvendo dados pessoais com risco ou dano relevante, observa o art. 48 da LGPD e a Resolução CD/ANPD nº 15/2024."),

(S, T18, "O dever de adotar medidas de segurança, técnicas e administrativas, aptas a proteger os dados pessoais, deve ser observado desde a fase de concepção do produto ou do serviço até a sua execução, nos termos da LGPD.", "C", "Art. 46, caput e § 2º, da Lei nº 13.709/2018, base normativa do que se denomina privacidade desde a concepção (privacy by design)."),
(S, T18, "O art. 46 da LGPD exige, como condição de licitude do tratamento, a certificação do controlador na norma ISO/IEC 27001.", "E", "O art. 46 determina a adoção de medidas de segurança compatíveis com o risco, desde a concepção até a execução, mas não impõe certificação específica em ISO/IEC 27001 como condição de licitude."),
(S, T18, "Anonimização, nos termos da LGPD, é a utilização de meios razoáveis e disponíveis no momento do tratamento, por meio dos quais um dado perde a possibilidade de associação, direta ou indireta, a um indivíduo.", "C", "Art. 5º, XI, da Lei nº 13.709/2018."),
(S, T18, "O dado pseudonimizado, por si só, deixa de ser considerado dado pessoal para os efeitos da LGPD.", "E", "Dado pessoal é a informação relacionada a pessoa natural identificada ou identificável (art. 5º, I). A pseudonimização (art. 13, § 4º) mantém a possibilidade de reidentificação com informação adicional. Somente o dado anonimizado, quando o processo não for reversível com esforços razoáveis, deixa de ser considerado dado pessoal (art. 12)."),
(S, T18, "A integridade de uma imagem forense deve ser verificada pelo recálculo do hash e pela comparação com o valor originalmente registrado.", "C", "A igualdade dos hashes indica que o conteúdo não foi alterado. Essa verificação documenta a integridade da evidência e apoia a cadeia de custódia (arts. 158-A a 158-F do CPP; ISO/IEC 27037)."),
(S, T18, "Em perícia digital, é boa prática trabalhar preferencialmente sobre a mídia original ligada em modo de escrita, para que as alterações feitas pelo perito comprovem a autenticidade do exame.", "E", "A boa prática é preservar a mídia original (por exemplo, com write blocker) e trabalhar sobre cópia bit a bit verificada por hash. Alterar o original compromete a integridade e a cadeia de custódia."),
]
